'use client'

import React, { useState, useCallback } from 'react'
import { Upload, FileText, Zap, Shield, Download, Check, X, Menu } from 'lucide-react'

export default function HomePage() {
  const [files, setFiles] = useState<File[]>([])
  const [merging, setMerging] = useState(false)
  const [mergedPdfUrl, setMergedPdfUrl] = useState<string | null>(null)
  const [dragActive, setDragActive] = useState(false)

  const handleDrag = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true)
    } else if (e.type === "dragleave") {
      setDragActive(false)
    }
  }, [])

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setDragActive(false)
    
    const droppedFiles = Array.from(e.dataTransfer.files).filter(
      file => file.type === 'application/pdf'
    )
    setFiles(prev => [...prev, ...droppedFiles])
  }, [])

  const handleFileInput = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const selectedFiles = Array.from(e.target.files).filter(
        file => file.type === 'application/pdf'
      )
      setFiles(prev => [...prev, ...selectedFiles])
    }
  }

  const removeFile = (index: number) => {
    setFiles(prev => prev.filter((_, i) => i !== index))
  }

  const mergePDFs = async () => {
    if (files.length < 2) {
      alert('Please add at least 2 PDF files to merge')
      return
    }

    setMerging(true)
    
    try {
      // Import pdf-lib dynamically
      const { PDFDocument } = await import('pdf-lib')
      
      const mergedPdf = await PDFDocument.create()
      
      for (const file of files) {
        const arrayBuffer = await file.arrayBuffer()
        const pdf = await PDFDocument.load(arrayBuffer)
        const copiedPages = await mergedPdf.copyPages(pdf, pdf.getPageIndices())
        copiedPages.forEach((page) => mergedPdf.addPage(page))
      }
      
      const mergedPdfBytes = await mergedPdf.save()
      const blob = new Blob([mergedPdfBytes], { type: 'application/pdf' })
      const url = URL.createObjectURL(blob)
      
      setMergedPdfUrl(url)
    } catch (error) {
      console.error('Error merging PDFs:', error)
      alert('Error merging PDFs. Please try again.')
    } finally {
      setMerging(false)
    }
  }

  const downloadMergedPdf = () => {
    if (!mergedPdfUrl) return
    const a = document.createElement('a')
    a.href = mergedPdfUrl
    a.download = 'merged.pdf'
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)
  }

  const resetTool = () => {
    setFiles([])
    setMergedPdfUrl(null)
    if (mergedPdfUrl) {
      URL.revokeObjectURL(mergedPdfUrl)
    }
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-950 via-slate-900 to-slate-950 text-white">
      {/* Noise texture overlay */}
      <div className="fixed inset-0 pointer-events-none opacity-[0.03] z-[1]" 
           style={{
             backgroundImage: `url("data:image/svg+xml,%3Csvg viewBox='0 0 400 400' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E")`
           }} 
      />
      
      {/* Header */}
      <header className="relative z-10 border-b border-slate-800">
        <div className="max-w-7xl mx-auto px-4 py-6 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg flex items-center justify-center">
              <FileText className="w-6 h-6" />
            </div>
            <span className="text-2xl font-bold font-mono">PDFKit</span>
          </div>
          <nav className="hidden md:flex gap-8 text-sm">
            <a href="#tools" className="hover:text-blue-400 transition-colors">Tools</a>
            <a href="#features" className="hover:text-blue-400 transition-colors">Features</a>
            <a href="#pricing" className="hover:text-blue-400 transition-colors">Pricing</a>
          </nav>
          <button className="bg-blue-600 hover:bg-blue-700 px-6 py-2 rounded-lg text-sm font-medium transition-colors">
            Sign In
          </button>
        </div>
      </header>

      {/* Hero Section */}
      <section className="relative z-10 max-w-7xl mx-auto px-4 pt-20 pb-16">
        <div className="text-center max-w-4xl mx-auto mb-16">
          <div className="inline-flex items-center gap-2 bg-blue-500/10 border border-blue-500/20 rounded-full px-4 py-2 mb-6">
            <div className="w-2 h-2 bg-green-400 rounded-full animate-pulse" />
            <span className="text-sm font-mono text-blue-300">Your files never leave your browser</span>
          </div>
          
          <h1 className="text-6xl md:text-7xl font-bold mb-6 leading-tight">
            PDF Tools That
            <br />
            <span className="bg-gradient-to-r from-blue-500 via-purple-500 to-pink-500 bg-clip-text text-transparent">
              Actually Work
            </span>
          </h1>
          
          <p className="text-xl text-slate-400 mb-8 max-w-2xl mx-auto">
            Merge, compress, split, and convert PDFs instantly. Client-side processing means your files stay private and processing is lightning fast.
          </p>
          
          <div className="flex flex-wrap gap-4 justify-center">
            <button className="bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 px-8 py-4 rounded-lg font-medium flex items-center gap-2 transition-all hover:scale-105 hover:shadow-lg hover:shadow-blue-500/50">
              <Zap className="w-5 h-5" />
              Try Free Now
            </button>
            <button className="border border-slate-700 hover:border-slate-600 px-8 py-4 rounded-lg font-medium transition-colors">
              View All Tools
            </button>
          </div>
        </div>

        {/* PDF Merge Tool */}
        <div className="bg-gradient-to-br from-blue-500/10 to-purple-500/10 border border-blue-500/20 rounded-2xl p-8 max-w-4xl mx-auto backdrop-blur-sm shadow-xl shadow-blue-500/10 hover:border-blue-500/40 transition-all">
          <div className="mb-6">
            <h2 className="text-2xl font-bold mb-2 flex items-center gap-3">
              <div className="w-8 h-8 bg-blue-500/20 rounded-lg flex items-center justify-center">
                <FileText className="w-5 h-5 text-blue-400" />
              </div>
              Merge PDFs
            </h2>
            <p className="text-slate-400">Combine multiple PDF files into one document</p>
          </div>

          {!mergedPdfUrl ? (
            <>
              {/* Upload Area */}
              <div
                className={`border-2 border-dashed rounded-xl p-12 text-center transition-all ${
                  dragActive 
                    ? 'border-blue-500 bg-blue-500/10' 
                    : 'border-slate-700 hover:border-slate-600'
                }`}
                onDragEnter={handleDrag}
                onDragLeave={handleDrag}
                onDragOver={handleDrag}
                onDrop={handleDrop}
              >
                <Upload className="w-12 h-12 mx-auto mb-4 text-slate-500" />
                <p className="text-lg mb-2">Drop PDF files here or click to browse</p>
                <p className="text-sm text-slate-500 mb-4">Support for multiple files</p>
                <input
                  type="file"
                  id="file-input"
                  multiple
                  accept="application/pdf"
                  onChange={handleFileInput}
                  className="hidden"
                />
                <label
                  htmlFor="file-input"
                  className="inline-block bg-slate-800 hover:bg-slate-700 px-6 py-3 rounded-lg cursor-pointer transition-colors"
                >
                  Select Files
                </label>
              </div>

              {/* File List */}
              {files.length > 0 && (
                <div className="mt-6 space-y-2">
                  <div className="flex justify-between items-center mb-3">
                    <p className="text-sm text-slate-400">{files.length} file(s) selected</p>
                    <button 
                      onClick={() => setFiles([])} 
                      className="text-sm text-red-400 hover:text-red-300 transition-colors"
                    >
                      Clear All
                    </button>
                  </div>
                  
                  {files.map((file, index) => (
                    <div 
                      key={index} 
                      className="flex items-center justify-between bg-slate-800/50 rounded-lg p-4 animate-[slideIn_0.3s_ease-out]"
                    >
                      <div className="flex items-center gap-3">
                        <FileText className="w-5 h-5 text-blue-400" />
                        <span className="font-mono text-sm">{file.name}</span>
                        <span className="text-xs text-slate-500">
                          {(file.size / 1024).toFixed(1)} KB
                        </span>
                      </div>
                      <button
                        onClick={() => removeFile(index)}
                        className="text-slate-500 hover:text-red-400 transition-colors"
                      >
                        <X className="w-5 h-5" />
                      </button>
                    </div>
                  ))}
                  
                  <button
                    onClick={mergePDFs}
                    disabled={merging || files.length < 2}
                    className="w-full bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 py-4 rounded-lg font-medium mt-4 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2 transition-all hover:scale-[1.02]"
                  >
                    {merging ? (
                      <>
                        <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin" />
                        Merging PDFs...
                      </>
                    ) : (
                      <>
                        <Zap className="w-5 h-5" />
                        Merge {files.length} PDFs
                      </>
                    )}
                  </button>
                </div>
              )}
            </>
          ) : (
            /* Success State */
            <div className="text-center py-12">
              <div className="w-20 h-20 bg-green-500/20 rounded-full flex items-center justify-center mx-auto mb-6">
                <Check className="w-10 h-10 text-green-400" />
              </div>
              <h3 className="text-2xl font-bold mb-2">PDF Merged Successfully!</h3>
              <p className="text-slate-400 mb-8">Your merged PDF is ready to download</p>
              
              <div className="flex gap-4 justify-center">
                <button
                  onClick={downloadMergedPdf}
                  className="bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 px-8 py-4 rounded-lg font-medium flex items-center gap-2 transition-all hover:scale-105"
                >
                  <Download className="w-5 h-5" />
                  Download Merged PDF
                </button>
                <button
                  onClick={resetTool}
                  className="border border-slate-700 hover:border-slate-600 px-8 py-4 rounded-lg font-medium transition-colors"
                >
                  Merge Another
                </button>
              </div>
            </div>
          )}
        </div>
      </section>

      {/* Features Section */}
      <section id="features" className="relative z-10 max-w-7xl mx-auto px-4 py-20">
        <div className="text-center mb-16">
          <h2 className="text-4xl font-bold mb-4">Why Choose PDFKit?</h2>
          <p className="text-slate-400 text-lg">Built for speed, privacy, and simplicity</p>
        </div>
        
        <div className="grid md:grid-cols-3 gap-8">
          {[
            {
              icon: Zap,
              title: 'Lightning Fast',
              description: 'Client-side processing means instant results. No uploading, no waiting, no servers.',
              color: 'blue'
            },
            {
              icon: Shield,
              title: '100% Private',
              description: 'Your files never leave your browser. We can\'t see them, nobody can. Complete privacy.',
              color: 'purple'
            },
            {
              icon: FileText,
              title: 'All Tools Included',
              description: 'Merge, split, compress, convert, and more. Everything you need for PDF management.',
              color: 'pink'
            }
          ].map((feature, index) => (
            <div key={index} className="bg-gradient-to-br from-blue-500/10 to-purple-500/10 border border-blue-500/20 rounded-xl p-8 hover:border-blue-500/40 transition-all hover:shadow-lg hover:shadow-blue-500/10 group">
              <div className={`w-14 h-14 bg-${feature.color}-500/20 rounded-xl flex items-center justify-center mb-6 group-hover:scale-110 transition-transform`}>
                <feature.icon className={`w-7 h-7 text-${feature.color}-400`} />
              </div>
              <h3 className="text-xl font-bold mb-3">{feature.title}</h3>
              <p className="text-slate-400">
                {feature.description}
              </p>
            </div>
          ))}
        </div>
      </section>

      {/* Pricing Section */}
      <section id="pricing" className="relative z-10 max-w-7xl mx-auto px-4 py-20">
        <div className="text-center mb-16">
          <h2 className="text-4xl font-bold mb-4">Simple, Transparent Pricing</h2>
          <p className="text-slate-400 text-lg">Start free, upgrade when you need more</p>
        </div>
        
        <div className="grid md:grid-cols-2 gap-8 max-w-4xl mx-auto">
          {/* Free Plan */}
          <div className="border border-slate-800 rounded-2xl p-8 hover:border-slate-700 transition-colors">
            <h3 className="text-2xl font-bold mb-2">Free</h3>
            <p className="text-slate-400 mb-6">Perfect for occasional use</p>
            <div className="text-4xl font-bold mb-8">
              $0<span className="text-lg text-slate-500 font-normal">/month</span>
            </div>
            <ul className="space-y-4 mb-8">
              {[
                '5 operations per day',
                'Max file size: 10MB',
                'Basic tools'
              ].map((feature, index) => (
                <li key={index} className="flex items-start gap-3">
                  <Check className="w-5 h-5 text-green-400 mt-0.5 flex-shrink-0" />
                  <span className="text-slate-300">{feature}</span>
                </li>
              ))}
            </ul>
            <button className="w-full border border-slate-700 hover:border-slate-600 py-3 rounded-lg transition-colors">
              Get Started
            </button>
          </div>
          
          {/* Premium Plan */}
          <div className="bg-gradient-to-br from-blue-500/10 to-purple-500/10 border border-blue-500/20 rounded-2xl p-8 relative hover:border-blue-500/40 transition-all">
            <div className="absolute -top-4 right-8 bg-gradient-to-r from-blue-500 to-purple-600 px-4 py-1 rounded-full text-sm font-medium">
              Popular
            </div>
            <h3 className="text-2xl font-bold mb-2">Premium</h3>
            <p className="text-slate-400 mb-6">For power users</p>
            <div className="text-4xl font-bold mb-2">
              $9<span className="text-lg text-slate-500 font-normal">/month</span>
            </div>
            <p className="text-sm text-slate-500 mb-8">or $79/year (save 26%)</p>
            <ul className="space-y-4 mb-8">
              {[
                'Unlimited operations',
                'No file size limits',
                'All advanced tools',
                'OCR & batch processing',
                'API access'
              ].map((feature, index) => (
                <li key={index} className="flex items-start gap-3">
                  <Check className="w-5 h-5 text-blue-400 mt-0.5 flex-shrink-0" />
                  <span className="text-slate-300">{feature}</span>
                </li>
              ))}
            </ul>
            <button className="w-full bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 py-3 rounded-lg transition-all hover:scale-[1.02]">
              Start Free Trial
            </button>
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="relative z-10 border-t border-slate-800 mt-20">
        <div className="max-w-7xl mx-auto px-4 py-12">
          <div className="grid md:grid-cols-4 gap-8 mb-8">
            <div>
              <div className="flex items-center gap-2 mb-4">
                <div className="w-8 h-8 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg flex items-center justify-center">
                  <FileText className="w-5 h-5" />
                </div>
                <span className="text-xl font-bold font-mono">PDFKit</span>
              </div>
              <p className="text-slate-400 text-sm">
                Fast, private, and powerful PDF tools for everyone.
              </p>
            </div>
            
            {[
              {
                title: 'Tools',
                links: ['Merge PDF', 'Split PDF', 'Compress PDF', 'Convert PDF']
              },
              {
                title: 'Company',
                links: ['About', 'Blog', 'API', 'Pricing']
              },
              {
                title: 'Legal',
                links: ['Privacy', 'Terms', 'Security', 'Contact']
              }
            ].map((column, index) => (
              <div key={index}>
                <h4 className="font-bold mb-4">{column.title}</h4>
                <ul className="space-y-2 text-sm text-slate-400">
                  {column.links.map((link, linkIndex) => (
                    <li key={linkIndex}>
                      <a href="#" className="hover:text-white transition-colors">{link}</a>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
          
          <div className="border-t border-slate-800 pt-8 text-center text-sm text-slate-500">
            © 2025 PDFKit. All rights reserved. Built with ❤️ for privacy-conscious users.
          </div>
        </div>
      </footer>
    </div>
  )
}